class ChecklistItem {const ChecklistItem({required this.id,required this.title,this.note='',this.state='todo'});final String id,title,note,state;Map<String,Object?> toMap()=>{'id':id,'title':title,'note':note,'state':state};factory ChecklistItem.fromMap(Map<String,Object?> m)=>ChecklistItem(id:m['id'] as String,title:m['title'] as String,note:m['note'] as String? ?? '',state:m['state'] as String? ?? 'todo');}
class Checklist {const Checklist({required this.id,required this.title,required this.category,required this.items,this.petId,this.species='both'});final String id,title,category,species;final String? petId;final List<ChecklistItem> items;Map<String,Object?> toMap()=>{'id':id,'title':title,'category':category,'petId':petId,'species':species,'items':items.map((e)=>e.toMap()).toList()};factory Checklist.fromMap(Map<String,Object?> m)=>Checklist(id:m['id'] as String,title:m['title'] as String,category:m['category'] as String,petId:m['petId'] as String?,species:m['species'] as String? ?? 'both',items:(m['items'] as List? ?? []).map((e)=>ChecklistItem.fromMap(Map<String,Object?>.from(e as Map))).toList());}
